-- Phase 5.8 campaign, automation, compliance and analytics storage.
create table public.restaurant_marketing_templates(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null check(char_length(name) between 1 and 120),subject text,preview_text text,html_content text not null default '',text_content text,cta_label text,cta_url text,image_url text,branding jsonb not null default '{}'::jsonb,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,name));
create table public.restaurant_marketing_campaigns(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null check(char_length(name) between 1 and 160),campaign_type text not null check(campaign_type in('one_off','scheduled','recurring','triggered')),status text not null default 'draft' check(status in('draft','scheduled','active','paused','completed','cancelled')),channels text[] not null default array['email']::text[] check(channels<@array['email','in_app','push']::text[] and cardinality(channels)>0),segment_key text,custom_segment_id uuid references public.restaurant_customer_segments(id) on delete set null,subject text,preview_text text,html_content text not null default '',text_content text,cta_label text,cta_url text,image_url text,promotion_id uuid references public.restaurant_promotions(id) on delete set null,reward_catalogue_id uuid references public.restaurant_loyalty_rewards(id) on delete set null,template_id uuid references public.restaurant_marketing_templates(id) on delete set null,branding jsonb not null default '{}'::jsonb,timezone text not null default 'Europe/London',scheduled_at timestamptz,next_run_at timestamptz,recurrence_unit text check(recurrence_unit is null or recurrence_unit in('day','week','month')),recurrence_interval integer check(recurrence_interval is null or recurrence_interval between 1 and 365),starts_at timestamptz,ends_at timestamptz,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_run_at timestamptz);
create table public.restaurant_marketing_campaign_runs(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.restaurant_marketing_campaigns(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,scheduled_for timestamptz not null,status text not null default 'queued' check(status in('queued','processing','completed','failed')),audience_count integer not null default 0,queued_count integer not null default 0,suppression_count integer not null default 0,error text,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(campaign_id,scheduled_for));
create table public.restaurant_marketing_automations(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null check(char_length(name) between 1 and 160),description text,trigger_type text not null,trigger_config jsonb not null default '{}'::jsonb,exit_conditions jsonb not null default '{}'::jsonb,cooldown_days integer not null default 30 check(cooldown_days between 1 and 3650),status text not null default 'draft' check(status in('draft','active','paused','archived')),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_evaluated_at timestamptz);
create table public.restaurant_marketing_automation_steps(id uuid primary key default gen_random_uuid(),automation_id uuid not null references public.restaurant_marketing_automations(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,position integer not null check(position>=1),step_type text not null check(step_type in('delay','condition','send','exit')),delay_minutes integer check(delay_minutes is null or delay_minutes>=0),condition_config jsonb not null default '{}'::jsonb,channels text[] not null default array['email']::text[] check(channels<@array['email','in_app','push']::text[]),subject text,preview_text text,html_content text,text_content text,cta_label text,cta_url text,image_url text,promotion_id uuid references public.restaurant_promotions(id) on delete set null,reward_catalogue_id uuid references public.restaurant_loyalty_rewards(id) on delete set null,true_next_position integer,false_next_position integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(automation_id,position));
create table public.restaurant_marketing_automation_runs(id uuid primary key default gen_random_uuid(),automation_id uuid not null references public.restaurant_marketing_automations(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,customer_user_id uuid not null references auth.users(id) on delete cascade,trigger_key text not null,status text not null default 'running' check(status in('running','waiting','completed','exited','failed')),current_position integer not null default 1,next_action_at timestamptz not null default now(),step_started_at timestamptz,error text,started_at timestamptz not null default now(),completed_at timestamptz,updated_at timestamptz not null default now(),unique(automation_id,customer_user_id,trigger_key));
create table public.restaurant_marketing_deliveries(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,campaign_id uuid references public.restaurant_marketing_campaigns(id) on delete cascade,campaign_run_id uuid references public.restaurant_marketing_campaign_runs(id) on delete cascade,automation_id uuid references public.restaurant_marketing_automations(id) on delete set null,automation_run_id uuid references public.restaurant_marketing_automation_runs(id) on delete cascade,automation_step_id uuid references public.restaurant_marketing_automation_steps(id) on delete set null,customer_user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in('email','in_app','push')),recipient_email text,subject text,preview_text text,html_content text,text_content text,cta_label text,cta_url text,image_url text,status text not null default 'queued' check(status in('queued','processing','sent','delivered','opened','clicked','failed','suppressed')),provider_message_id text,attempts integer not null default 0,available_at timestamptz not null default now(),last_error text,sent_at timestamptz,delivered_at timestamptz,opened_at timestamptz,clicked_at timestamptz,failed_at timestamptz,dedupe_key text not null unique,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.restaurant_marketing_delivery_events(id uuid primary key default gen_random_uuid(),delivery_id uuid not null references public.restaurant_marketing_deliveries(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,event_type text not null,provider_event_id text,event_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(provider_event_id));
create table public.restaurant_marketing_suppressions(id uuid primary key default gen_random_uuid(),restaurant_id uuid references public.restaurants(id) on delete cascade,customer_user_id uuid references auth.users(id) on delete cascade,email text,channel text not null default 'email' check(channel in('email','in_app','push')),reason text not null check(reason in('unsubscribe','bounce','complaint','admin','fraud','invalid')),source text,expires_at timestamptz,created_at timestamptz not null default now(),unique nulls not distinct(restaurant_id,customer_user_id,email,channel,reason));
create table public.restaurant_marketing_unsubscribe_tokens(id uuid primary key default gen_random_uuid(),delivery_id uuid not null unique references public.restaurant_marketing_deliveries(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,customer_user_id uuid not null references auth.users(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null default(now()+interval '180 days'),used_at timestamptz,created_at timestamptz not null default now());
create table public.restaurant_marketing_conversions(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,order_id uuid not null unique references public.orders(id) on delete cascade,delivery_id uuid references public.restaurant_marketing_deliveries(id) on delete set null,campaign_id uuid references public.restaurant_marketing_campaigns(id) on delete set null,automation_id uuid references public.restaurant_marketing_automations(id) on delete set null,customer_user_id uuid references auth.users(id) on delete set null,revenue_pence integer not null default 0,reward_cost_pence integer not null default 0,attributed_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.restaurant_marketing_audit_log(id uuid primary key default gen_random_uuid(),restaurant_id uuid references public.restaurants(id) on delete cascade,actor_user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index marketing_campaign_due_idx on public.restaurant_marketing_campaigns(status,next_run_at) where status in('scheduled','active');create index marketing_delivery_queue_idx on public.restaurant_marketing_deliveries(status,available_at,created_at) where status in('queued','failed');create index marketing_delivery_customer_idx on public.restaurant_marketing_deliveries(restaurant_id,customer_user_id,created_at desc);create index marketing_delivery_provider_idx on public.restaurant_marketing_deliveries(provider_message_id) where provider_message_id is not null;create index marketing_events_delivery_idx on public.restaurant_marketing_delivery_events(delivery_id,event_at desc);create index marketing_automation_due_idx on public.restaurant_marketing_automation_runs(status,next_action_at) where status in('running','waiting');create index marketing_suppressions_lookup_idx on public.restaurant_marketing_suppressions(restaurant_id,customer_user_id,email,channel);create index marketing_conversions_campaign_idx on public.restaurant_marketing_conversions(restaurant_id,campaign_id,attributed_at desc);
alter table public.restaurant_marketing_templates enable row level security;alter table public.restaurant_marketing_campaigns enable row level security;alter table public.restaurant_marketing_campaign_runs enable row level security;alter table public.restaurant_marketing_automations enable row level security;alter table public.restaurant_marketing_automation_steps enable row level security;alter table public.restaurant_marketing_automation_runs enable row level security;alter table public.restaurant_marketing_deliveries enable row level security;alter table public.restaurant_marketing_delivery_events enable row level security;alter table public.restaurant_marketing_suppressions enable row level security;alter table public.restaurant_marketing_unsubscribe_tokens enable row level security;alter table public.restaurant_marketing_conversions enable row level security;alter table public.restaurant_marketing_audit_log enable row level security;
do $$ declare t text;begin foreach t in array array['restaurant_marketing_templates','restaurant_marketing_campaigns','restaurant_marketing_campaign_runs','restaurant_marketing_automations','restaurant_marketing_automation_steps','restaurant_marketing_automation_runs','restaurant_marketing_deliveries','restaurant_marketing_delivery_events','restaurant_marketing_suppressions','restaurant_marketing_unsubscribe_tokens','restaurant_marketing_conversions','restaurant_marketing_audit_log'] loop execute format('create policy %I on public.%I for select using (public.is_restaurant_member(restaurant_id) or public.is_platform_admin())',t||'_member_select',t);end loop;end $$;
revoke insert,update,delete,truncate on public.restaurant_marketing_templates,public.restaurant_marketing_campaigns,public.restaurant_marketing_campaign_runs,public.restaurant_marketing_automations,public.restaurant_marketing_automation_steps,public.restaurant_marketing_automation_runs,public.restaurant_marketing_deliveries,public.restaurant_marketing_delivery_events,public.restaurant_marketing_suppressions,public.restaurant_marketing_unsubscribe_tokens,public.restaurant_marketing_conversions,public.restaurant_marketing_audit_log from anon,authenticated;grant select on public.restaurant_marketing_templates,public.restaurant_marketing_campaigns,public.restaurant_marketing_campaign_runs,public.restaurant_marketing_automations,public.restaurant_marketing_automation_steps,public.restaurant_marketing_automation_runs,public.restaurant_marketing_deliveries,public.restaurant_marketing_delivery_events,public.restaurant_marketing_suppressions,public.restaurant_marketing_conversions,public.restaurant_marketing_audit_log to authenticated;
create or replace function public.marketing_member_restaurant_id() returns uuid language sql stable security definer set search_path='' as $$select rm.restaurant_id from public.restaurant_members rm where rm.user_id=auth.uid() order by rm.created_at limit 1$$;
create or replace function public.save_restaurant_marketing_campaign(p_campaign jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_id uuid;v_type text:=coalesce(p_campaign->>'campaign_type','one_off');v_status text:=coalesce(p_campaign->>'status','draft');v_scheduled timestamptz:=nullif(p_campaign->>'scheduled_at','')::timestamptz;begin if v_restaurant is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;if v_type not in('one_off','scheduled','recurring','triggered') or v_status not in('draft','scheduled','active','paused') then raise exception 'Invalid campaign configuration';end if;if nullif(p_campaign->>'id','') is null then insert into public.restaurant_marketing_campaigns(restaurant_id,name,campaign_type,status,channels,segment_key,custom_segment_id,subject,preview_text,html_content,text_content,cta_label,cta_url,image_url,promotion_id,reward_catalogue_id,template_id,branding,timezone,scheduled_at,next_run_at,recurrence_unit,recurrence_interval,starts_at,ends_at,created_by) values(v_restaurant,btrim(p_campaign->>'name'),v_type,v_status,coalesce(array(select jsonb_array_elements_text(coalesce(p_campaign->'channels','["email"]'))),array['email']),nullif(p_campaign->>'segment_key',''),nullif(p_campaign->>'custom_segment_id','')::uuid,p_campaign->>'subject',p_campaign->>'preview_text',coalesce(p_campaign->>'html_content',''),p_campaign->>'text_content',p_campaign->>'cta_label',p_campaign->>'cta_url',p_campaign->>'image_url',nullif(p_campaign->>'promotion_id','')::uuid,nullif(p_campaign->>'reward_catalogue_id','')::uuid,nullif(p_campaign->>'template_id','')::uuid,coalesce(p_campaign->'branding','{}'),coalesce(nullif(p_campaign->>'timezone',''),'Europe/London'),v_scheduled,case when v_status in('scheduled','active') then coalesce(v_scheduled,now()) end,nullif(p_campaign->>'recurrence_unit',''),coalesce(nullif(p_campaign->>'recurrence_interval','')::int,1),nullif(p_campaign->>'starts_at','')::timestamptz,nullif(p_campaign->>'ends_at','')::timestamptz,auth.uid()) returning id into v_id;else v_id:=(p_campaign->>'id')::uuid;update public.restaurant_marketing_campaigns set name=btrim(p_campaign->>'name'),campaign_type=v_type,status=v_status,channels=coalesce(array(select jsonb_array_elements_text(coalesce(p_campaign->'channels','["email"]'))),array['email']),segment_key=nullif(p_campaign->>'segment_key',''),custom_segment_id=nullif(p_campaign->>'custom_segment_id','')::uuid,subject=p_campaign->>'subject',preview_text=p_campaign->>'preview_text',html_content=coalesce(p_campaign->>'html_content',''),text_content=p_campaign->>'text_content',cta_label=p_campaign->>'cta_label',cta_url=p_campaign->>'cta_url',image_url=p_campaign->>'image_url',promotion_id=nullif(p_campaign->>'promotion_id','')::uuid,reward_catalogue_id=nullif(p_campaign->>'reward_catalogue_id','')::uuid,template_id=nullif(p_campaign->>'template_id','')::uuid,branding=coalesce(p_campaign->'branding','{}'),timezone=coalesce(nullif(p_campaign->>'timezone',''),'Europe/London'),scheduled_at=v_scheduled,next_run_at=case when v_status in('scheduled','active') then coalesce(v_scheduled,next_run_at,now()) else null end,recurrence_unit=nullif(p_campaign->>'recurrence_unit',''),recurrence_interval=coalesce(nullif(p_campaign->>'recurrence_interval','')::int,1),starts_at=nullif(p_campaign->>'starts_at','')::timestamptz,ends_at=nullif(p_campaign->>'ends_at','')::timestamptz,updated_at=now() where id=v_id and restaurant_id=v_restaurant;if not found then raise exception 'Campaign not found';end if;end if;insert into public.restaurant_marketing_audit_log(restaurant_id,actor_user_id,action,entity_type,entity_id,details) values(v_restaurant,auth.uid(),'campaign_saved','campaign',v_id,jsonb_build_object('status',v_status,'type',v_type));return v_id;end$$;
create or replace function public.set_restaurant_marketing_campaign_status(p_campaign_id uuid,p_status text) returns boolean language plpgsql security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();begin if p_status not in('draft','scheduled','active','paused','cancelled') then raise exception 'Invalid status';end if;update public.restaurant_marketing_campaigns set status=p_status,next_run_at=case when p_status in('scheduled','active') then coalesce(next_run_at,scheduled_at,now()) else null end,updated_at=now() where id=p_campaign_id and restaurant_id=v_restaurant;if not found then raise exception 'Campaign not found' using errcode='42501';end if;insert into public.restaurant_marketing_audit_log(restaurant_id,actor_user_id,action,entity_type,entity_id,details) values(v_restaurant,auth.uid(),'campaign_status_changed','campaign',p_campaign_id,jsonb_build_object('status',p_status));return true;end$$;
create or replace function public.save_restaurant_marketing_template(p_template jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_id uuid;begin if v_restaurant is null then raise exception 'Restaurant membership not found';end if;if nullif(p_template->>'id','') is null then insert into public.restaurant_marketing_templates(restaurant_id,name,subject,preview_text,html_content,text_content,cta_label,cta_url,image_url,branding,created_by) values(v_restaurant,btrim(p_template->>'name'),p_template->>'subject',p_template->>'preview_text',coalesce(p_template->>'html_content',''),p_template->>'text_content',p_template->>'cta_label',p_template->>'cta_url',p_template->>'image_url',coalesce(p_template->'branding','{}'),auth.uid()) returning id into v_id;else v_id:=(p_template->>'id')::uuid;update public.restaurant_marketing_templates set name=btrim(p_template->>'name'),subject=p_template->>'subject',preview_text=p_template->>'preview_text',html_content=coalesce(p_template->>'html_content',''),text_content=p_template->>'text_content',cta_label=p_template->>'cta_label',cta_url=p_template->>'cta_url',image_url=p_template->>'image_url',branding=coalesce(p_template->'branding','{}'),updated_at=now() where id=v_id and restaurant_id=v_restaurant;if not found then raise exception 'Template not found';end if;end if;return v_id;end$$;
create or replace function public.save_restaurant_marketing_automation(p_automation jsonb,p_steps jsonb default '[]') returns uuid language plpgsql security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_id uuid;s jsonb;begin if v_restaurant is null then raise exception 'Restaurant membership not found';end if;if nullif(p_automation->>'id','') is null then insert into public.restaurant_marketing_automations(restaurant_id,name,description,trigger_type,trigger_config,exit_conditions,cooldown_days,status,created_by) values(v_restaurant,btrim(p_automation->>'name'),p_automation->>'description',coalesce(nullif(p_automation->>'trigger_type',''),'segment'),coalesce(p_automation->'trigger_config','{}'),coalesce(p_automation->'exit_conditions','{}'),coalesce(nullif(p_automation->>'cooldown_days','')::int,30),coalesce(nullif(p_automation->>'status',''),'draft'),auth.uid()) returning id into v_id;else v_id:=(p_automation->>'id')::uuid;update public.restaurant_marketing_automations set name=btrim(p_automation->>'name'),description=p_automation->>'description',trigger_type=coalesce(nullif(p_automation->>'trigger_type',''),'segment'),trigger_config=coalesce(p_automation->'trigger_config','{}'),exit_conditions=coalesce(p_automation->'exit_conditions','{}'),cooldown_days=coalesce(nullif(p_automation->>'cooldown_days','')::int,30),status=coalesce(nullif(p_automation->>'status',''),'draft'),updated_at=now() where id=v_id and restaurant_id=v_restaurant;if not found then raise exception 'Automation not found';end if;delete from public.restaurant_marketing_automation_steps where automation_id=v_id;end if;for s in select * from jsonb_array_elements(coalesce(p_steps,'[]')) loop insert into public.restaurant_marketing_automation_steps(automation_id,restaurant_id,position,step_type,delay_minutes,condition_config,channels,subject,preview_text,html_content,text_content,cta_label,cta_url,image_url,promotion_id,reward_catalogue_id,true_next_position,false_next_position) values(v_id,v_restaurant,(s->>'position')::int,s->>'step_type',nullif(s->>'delay_minutes','')::int,coalesce(s->'condition_config','{}'),coalesce(array(select jsonb_array_elements_text(coalesce(s->'channels','["email"]'))),array['email']),s->>'subject',s->>'preview_text',s->>'html_content',s->>'text_content',s->>'cta_label',s->>'cta_url',s->>'image_url',nullif(s->>'promotion_id','')::uuid,nullif(s->>'reward_catalogue_id','')::uuid,nullif(s->>'true_next_position','')::int,nullif(s->>'false_next_position','')::int);end loop;insert into public.restaurant_marketing_audit_log(restaurant_id,actor_user_id,action,entity_type,entity_id) values(v_restaurant,auth.uid(),'automation_saved','automation',v_id);return v_id;end$$;
create or replace function public.get_restaurant_marketing_workspace() returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_result jsonb;begin if v_restaurant is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;select jsonb_build_object('restaurant_id',v_restaurant,'settings',coalesce((select to_jsonb(s) from public.restaurant_marketing_settings s where s.restaurant_id=v_restaurant),jsonb_build_object('restaurant_id',v_restaurant,'timezone','Europe/London','quiet_hours_start','21:00','quiet_hours_end','08:00','high_spender_pence',10000,'low_spender_pence',3000,'referral_champion_threshold',3,'max_email_sends_per_day',5000,'max_notification_sends_per_day',10000,'max_sends_per_customer_per_day',3,'rate_limit_per_minute',250,'attribution_window_days',7)),'campaigns',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc) from public.restaurant_marketing_campaigns c where c.restaurant_id=v_restaurant),'[]'),'templates',coalesce((select jsonb_agg(to_jsonb(t) order by t.name) from public.restaurant_marketing_templates t where t.restaurant_id=v_restaurant),'[]'),'automations',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('steps',coalesce((select jsonb_agg(to_jsonb(st) order by st.position) from public.restaurant_marketing_automation_steps st where st.automation_id=a.id),'[]')) order by a.created_at desc) from public.restaurant_marketing_automations a where a.restaurant_id=v_restaurant),'[]'),'segments',public.get_restaurant_crm_segments(v_restaurant)) into v_result;return v_result;end$$;
create or replace function public.update_restaurant_marketing_settings(p_settings jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_result jsonb;begin if v_restaurant is null then raise exception 'Restaurant membership not found';end if;insert into public.restaurant_marketing_settings(restaurant_id,timezone,quiet_hours_start,quiet_hours_end,high_spender_pence,low_spender_pence,referral_champion_threshold,max_email_sends_per_day,max_notification_sends_per_day,max_sends_per_customer_per_day,rate_limit_per_minute,attribution_window_days,updated_at) values(v_restaurant,coalesce(nullif(p_settings->>'timezone',''),'Europe/London'),coalesce(nullif(p_settings->>'quiet_hours_start','')::time,'21:00'),coalesce(nullif(p_settings->>'quiet_hours_end','')::time,'08:00'),coalesce(nullif(p_settings->>'high_spender_pence','')::int,10000),coalesce(nullif(p_settings->>'low_spender_pence','')::int,3000),coalesce(nullif(p_settings->>'referral_champion_threshold','')::int,3),coalesce(nullif(p_settings->>'max_email_sends_per_day','')::int,5000),coalesce(nullif(p_settings->>'max_notification_sends_per_day','')::int,10000),coalesce(nullif(p_settings->>'max_sends_per_customer_per_day','')::int,3),coalesce(nullif(p_settings->>'rate_limit_per_minute','')::int,250),coalesce(nullif(p_settings->>'attribution_window_days','')::int,7),now()) on conflict(restaurant_id) do update set timezone=excluded.timezone,quiet_hours_start=excluded.quiet_hours_start,quiet_hours_end=excluded.quiet_hours_end,high_spender_pence=excluded.high_spender_pence,low_spender_pence=excluded.low_spender_pence,referral_champion_threshold=excluded.referral_champion_threshold,max_email_sends_per_day=excluded.max_email_sends_per_day,max_notification_sends_per_day=excluded.max_notification_sends_per_day,max_sends_per_customer_per_day=excluded.max_sends_per_customer_per_day,rate_limit_per_minute=excluded.rate_limit_per_minute,attribution_window_days=excluded.attribution_window_days,updated_at=now();select to_jsonb(s) into v_result from public.restaurant_marketing_settings s where s.restaurant_id=v_restaurant;return v_result;end$$;
create or replace function public.unsubscribe_marketing_by_token(p_token text) returns boolean language plpgsql security definer set search_path='' as $$declare v_token public.restaurant_marketing_unsubscribe_tokens%rowtype;v_email text;begin select * into v_token from public.restaurant_marketing_unsubscribe_tokens where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and used_at is null and expires_at>now() for update;if v_token.id is null then return false;end if;insert into public.customer_restaurant_marketing_preferences(restaurant_id,customer_user_id,marketing_emails,restaurant_opt_out,consent_updated_at,updated_at) values(v_token.restaurant_id,v_token.customer_user_id,false,true,now(),now()) on conflict(restaurant_id,customer_user_id) do update set marketing_emails=false,restaurant_opt_out=true,consent_updated_at=now(),updated_at=now();select email into v_email from auth.users where id=v_token.customer_user_id;insert into public.restaurant_marketing_suppressions(restaurant_id,customer_user_id,email,channel,reason,source) values(v_token.restaurant_id,v_token.customer_user_id,v_email,'email','unsubscribe','unsubscribe_link') on conflict do nothing;update public.restaurant_marketing_unsubscribe_tokens set used_at=now() where id=v_token.id;return true;end$$;
create or replace function public.attribute_marketing_order_conversion() returns trigger language plpgsql security definer set search_path='' as $$declare v_delivery public.restaurant_marketing_deliveries%rowtype;v_days integer;begin if new.payment_status<>'paid' or new.customer_user_id is null or new.order_status='rejected' then return new;end if;if tg_op='UPDATE' and old.payment_status='paid' then return new;end if;select coalesce(attribution_window_days,7) into v_days from public.restaurant_marketing_settings where restaurant_id=new.restaurant_id;v_days:=coalesce(v_days,7);select * into v_delivery from public.restaurant_marketing_deliveries d where d.restaurant_id=new.restaurant_id and d.customer_user_id=new.customer_user_id and d.sent_at is not null and d.sent_at>=new.created_at-(v_days||' days')::interval and d.sent_at<=now() and d.status in('sent','delivered','opened','clicked') order by coalesce(d.clicked_at,d.opened_at,d.sent_at) desc limit 1;if v_delivery.id is not null then insert into public.restaurant_marketing_conversions(restaurant_id,order_id,delivery_id,campaign_id,automation_id,customer_user_id,revenue_pence,reward_cost_pence) values(new.restaurant_id,new.id,v_delivery.id,v_delivery.campaign_id,v_delivery.automation_id,new.customer_user_id,new.total_pence,coalesce(new.discount_pence,0)+coalesce(new.reward_discount_pence,0)) on conflict(order_id) do nothing;end if;return new;end$$;create trigger orders_attribute_marketing_conversion after insert or update of payment_status on public.orders for each row execute function public.attribute_marketing_order_conversion();
create or replace function public.get_restaurant_marketing_reports(p_days integer default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_restaurant uuid:=public.marketing_member_restaurant_id();v_since timestamptz:=now()-(least(greatest(coalesce(p_days,90),1),730)||' days')::interval;v_result jsonb;begin if v_restaurant is null then raise exception 'Restaurant membership not found';end if;with stats as(select campaign_id,count(*) filter(where sent_at is not null) sent,count(*) filter(where delivered_at is not null) delivered,count(*) filter(where opened_at is not null) opened,count(*) filter(where clicked_at is not null) clicked from public.restaurant_marketing_deliveries where restaurant_id=v_restaurant and created_at>=v_since group by campaign_id),conv as(select campaign_id,count(*) orders,coalesce(sum(revenue_pence),0) revenue,coalesce(sum(reward_cost_pence),0) cost from public.restaurant_marketing_conversions where restaurant_id=v_restaurant and attributed_at>=v_since group by campaign_id) select jsonb_build_object('summary',jsonb_build_object('sent',coalesce(sum(s.sent),0),'delivered',coalesce(sum(s.delivered),0),'opened',coalesce(sum(s.opened),0),'clicked',coalesce(sum(s.clicked),0),'orders_generated',coalesce(sum(c.orders),0),'revenue_generated_pence',coalesce(sum(c.revenue),0),'reward_cost_pence',coalesce(sum(c.cost),0)),'campaigns',coalesce(jsonb_agg(jsonb_build_object('id',ca.id,'name',ca.name,'sent',coalesce(s.sent,0),'delivered',coalesce(s.delivered,0),'opened',coalesce(s.opened,0),'clicked',coalesce(s.clicked,0),'conversion_orders',coalesce(c.orders,0),'revenue_pence',coalesce(c.revenue,0),'reward_cost_pence',coalesce(c.cost,0)) order by coalesce(c.revenue,0) desc) filter(where ca.id is not null),'[]')) into v_result from public.restaurant_marketing_campaigns ca left join stats s on s.campaign_id=ca.id left join conv c on c.campaign_id=ca.id where ca.restaurant_id=v_restaurant;return v_result;end$$;
create or replace function public.get_platform_marketing_analytics(p_days integer default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_since timestamptz:=now()-(least(greatest(coalesce(p_days,90),1),730)||' days')::interval;v_result jsonb;begin if not public.is_platform_admin() then raise exception 'Platform admin access required' using errcode='42501';end if;select jsonb_build_object('restaurants_adopted',(select count(distinct restaurant_id) from public.restaurant_marketing_campaigns),'campaign_volume',(select count(*) from public.restaurant_marketing_campaign_runs where created_at>=v_since),'email_volume',(select count(*) from public.restaurant_marketing_deliveries where channel='email' and created_at>=v_since),'notifications_volume',(select count(*) from public.restaurant_marketing_deliveries where channel='in_app' and created_at>=v_since),'revenue_generated_pence',(select coalesce(sum(revenue_pence),0) from public.restaurant_marketing_conversions where attributed_at>=v_since),'reward_cost_pence',(select coalesce(sum(reward_cost_pence),0) from public.restaurant_marketing_conversions where attributed_at>=v_since),'engaged_customers',(select count(distinct customer_user_id) from public.restaurant_marketing_deliveries where created_at>=v_since and(opened_at is not null or clicked_at is not null)),'automation_usage',(select count(distinct restaurant_id) from public.restaurant_marketing_automations where status='active'),'active_automations',(select count(*) from public.restaurant_marketing_automations where status='active')) into v_result;return v_result;end$$;
create or replace function public.marketing_service_or_tenant_access(p_restaurant_id uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.role()='service_role' or public.is_restaurant_member(p_restaurant_id) or public.is_platform_admin()$$;
revoke all on function public.marketing_member_restaurant_id(),public.save_restaurant_marketing_campaign(jsonb),public.set_restaurant_marketing_campaign_status(uuid,text),public.save_restaurant_marketing_template(jsonb),public.save_restaurant_marketing_automation(jsonb,jsonb),public.get_restaurant_marketing_workspace(),public.update_restaurant_marketing_settings(jsonb),public.unsubscribe_marketing_by_token(text),public.get_restaurant_marketing_reports(integer),public.get_platform_marketing_analytics(integer),public.marketing_service_or_tenant_access(uuid) from public;
grant execute on function public.save_restaurant_marketing_campaign(jsonb),public.set_restaurant_marketing_campaign_status(uuid,text),public.save_restaurant_marketing_template(jsonb),public.save_restaurant_marketing_automation(jsonb,jsonb),public.get_restaurant_marketing_workspace(),public.update_restaurant_marketing_settings(jsonb),public.get_restaurant_marketing_reports(integer),public.get_platform_marketing_analytics(integer) to authenticated;grant execute on function public.unsubscribe_marketing_by_token(text) to anon,authenticated;
